// ---------------------------------------------------------------------------
//  Icons
// ---------------------------------------------------------------------------

namespace {

struct IconRef {
  const uint8_t *bits;
  int16_t w, h;
};

// A full-colour icon. `px` is RGB565 blitted with pushImage() rather than
// tinted; pixels equal to facicons::kTransparent are left alone, so one of
// these can sit on the alert ribbon as safely as on the panel background.
struct ColorIconRef {
  const uint16_t *px;
  int16_t w, h;
};

// The badge icon for a planet owner. Matched on a lowercased prefix so both
// the singular and plural spellings the API uses ("Automaton", "Terminids")
// land on the same icon.
//
// These three are full-colour RGB565, not 1-bit masks: the official insignia
// read as a lighter facet over a darker body, and that split is the whole
// identity of the Illuminate mark in particular -- reduced to one bit at badge
// size it is a featureless blob. They carry their own colour and are not
// tinted by the caller. See src/hud_faction_icons.h.
//
// There is deliberately no entry for "Humans": the SEAF emblem's detail does
// not survive the reduction to a badge-sized bitmap, so that badge takes the
// same text-only route as an owner we have no icon for at all.
ColorIconRef factionIcon(const String &faction) {
  String f = faction;
  f.toLowerCase();
  if (f.startsWith("automaton"))
    return {facicons::automaton, facicons::automatonW, facicons::automatonH};
  if (f.startsWith("terminid"))
    return {facicons::terminid, facicons::terminidW, facicons::terminidH};
  if (f.startsWith("illuminate"))
    return {facicons::illuminate, facicons::illuminateW, facicons::illuminateH};
  return {nullptr, 0, 0};  // SEAF / unknown owner: badge falls back to text only
}

// One chip per hazard kind. hazardFromName() in hd2_model.h has already turned
// the API's free-text hazard name into one of these; kHazardOther is the
// catch-all that keeps an unrecognised hazard visible rather than dropped.
IconRef hazardIcon(HazardKind k) {
  switch (k) {
    case kHazardFire:   return {icons::hazFire, icons::hazFireW, icons::hazFireH};
    case kHazardIon:    return {icons::hazIon, icons::hazIonW, icons::hazIonH};
    case kHazardCold:   return {icons::hazCold, icons::hazColdW, icons::hazColdH};
    case kHazardMeteor: return {icons::hazMeteor, icons::hazMeteorW, icons::hazMeteorH};
    case kHazardStorm:  return {icons::hazStorm, icons::hazStormW, icons::hazStormH};
    case kHazardTremor: return {icons::hazTremor, icons::hazTremorW, icons::hazTremorH};
    default:            return {icons::hazOther, icons::hazOtherW, icons::hazOtherH};
  }
}

// Source coordinate, in 24.8 fixed point, for destination pixel `d` when
// scaling `dstLen` pixels down onto `srcLen`. Half-pixel centred, so the
// interpolation is symmetric, and clamped at the left/top edge where the
// centring would otherwise read off the start of the array.
inline int32_t srcCoord(int32_t d, int32_t srcLen, int32_t dstLen) {
  const int32_t f = ((2 * d + 1) * srcLen * 256) / (2 * dstLen) - 128;
  return f < 0 ? 0 : f;
}

// Blend two RGB565 pixels, `t` running 0..255 from `a` to `b`. The channels are
// interpolated in their packed 5/6/5 precision, which is all the panel can show
// anyway.
inline uint16_t lerp565(uint16_t a, uint16_t b, int t) {
  const int ar = a >> 11, ag = (a >> 5) & 0x3F, ab = a & 0x1F;
  const int br = b >> 11, bg = (b >> 5) & 0x3F, bb = b & 0x1F;
  return (uint16_t)(((ar + (((br - ar) * t) >> 8)) << 11) |
                    ((ag + (((bg - ag) * t) >> 8)) << 5) |
                     (ab + (((bb - ab) * t) >> 8)));
}

}  // namespace

// ---------------------------------------------------------------------------
//  Small helpers
// ---------------------------------------------------------------------------

static String upper(const String &s) {
  String t = s;
  t.toUpperCase();
  return t;
}

// Humans holding a planet is good news; anyone else gets the red treatment.
static uint16_t factionColor(const String &faction) {
  return faction.equalsIgnoreCase("Humans") ? theme::green : theme::red;
}

// What to *call* a faction on screen. The API names our side "Humans"; the
// game calls them the SEAF, and that is what the card should say. Purely a
// relabelling at the point of drawing — every match above and in hd2_api.cpp
// still runs against the API's own spelling, which this never rewrites.
static String factionDisplayName(const String &faction) {
  String f = faction;
  f.toLowerCase();
  return f.startsWith("human") ? String(F("SEAF")) : faction;
}

// The card's accent, taken from whoever is attacking. Everything tinted by it
// — the alert ribbon, the scene weave, the invader's half of the tug-of-war —
// is describing that faction, so they all move together.
static uint16_t factionAccent(const String &faction) {
  String f = faction;
  f.toLowerCase();
  if (f.startsWith("illuminate")) return theme::purple;
  if (f.startsWith("terminid")) return theme::amber;
  if (f.startsWith("automaton")) return theme::red;
  if (f.startsWith("human")) return theme::blue;
  return theme::gold;
}

// Anchor point inside a w*h box for a given TFT_eSPI datum.
static void datumAnchor(uint8_t datum, int16_t w, int16_t h, int16_t &ax, int16_t &ay) {
  switch (datum) {
    case TC_DATUM: ax = w / 2; ay = 0;     break;
    case TR_DATUM: ax = w;     ay = 0;     break;
    case ML_DATUM: ax = 0;     ay = h / 2; break;
    case MC_DATUM: ax = w / 2; ay = h / 2; break;
    case MR_DATUM: ax = w;     ay = h / 2; break;
    default:       ax = 0;     ay = 0;     break;  // TL_DATUM
  }
}

// "Omega" -> "OMEGA SECTOR". The API gives the bare name; the card wants the
// full form the game uses.
static String sectorLabel(const String &sector) {
  if (!sector.length()) return String();
  String s = upper(sector);
  if (!s.endsWith(" SECTOR")) s += F(" SECTOR");
  return s;
}

// Player counts, grouped: 13637 -> "13,637".
//
// This used to zero-pad to six digits ("013,637") so the footer's left block
// kept a constant width and did not twitch as divers came and went. The
// padding read as part of the number rather than as alignment, so it is gone;
// the callers hold their own width instead — the strip's fixed column boxes
// now, the footer's own having gone with the diver count it cleared for.
// Width to clear for the footer's reward, in FONT_VALUE. Four digits is well
// past any medal award the game has issued, but the row has the space and a
// clipped number is a worse failure than a wide box; holding the box fixed
// also keeps a drop from 120 to 45 from leaving the hundreds digit standing.
static constexpr int16_t kRewardBoxW = 56;

// The footer's reward block, end to end, and the gap it leaves before the sync
// clock. That gap is where the uncalibrated-touch hint goes: it was left empty
// deliberately when the footer was reworked, and this is a caption that earns
// it -- a call to action that removes itself the moment it is acted on.
// Derived rather than declared so it cannot drift from the block beside it.
static constexpr int16_t kRewardBlockW = icons::medalW + footerIconGap + kRewardBoxW;
static constexpr int16_t kHintX = cardX + kRewardBlockW;
static constexpr int16_t kHintW = (contentR - syncBoxW) - kHintX;

static String formatCount(uint32_t v) {
  char digits[16];
  snprintf(digits, sizeof(digits), "%lu", (unsigned long)v);
  const int n = (int)strlen(digits);
  String out;
  out.reserve(n + n / 3);
  for (int i = 0; i < n; i++) {
    if (i && (n - i) % 3 == 0) out += ',';
    out += digits[i];
  }
  return out;
}

// A measured rate of change, e.g. "+04.426% / h". Zero-padded to a fixed width
// for the same reason as the player count.
static String formatRate(float pctPerHour) {
  float a = fabsf(pctPerHour);
  if (a > 99.999f) a = 99.999f;  // clamp rather than let the field jump width
  char buf[24];
  snprintf(buf, sizeof(buf), "%c%.1f%% / h", pctPerHour < 0.0f ? '-' : '+', a);
  return String(buf);
}

// The target currently on screen, or nullptr when the order has no tasks.
static const OrderTask *activeTask(const HudModel &m, uint8_t idx) {
  if (!m.order.valid || m.order.taskCount <= 0) return nullptr;
  if (idx >= (uint8_t)m.order.taskCount) idx = 0;
  return &m.order.tasks[idx];
}

// Pages in the unified carousel. An active Major Order owns the screen: High
// Command's orders are the point of the device, and rotating away from them
// to show a planet nobody was told to take buries the one thing that matters.
// The campaign cards are what fills the carousel when there is no order, not
// a second act alongside one. _pageIdx indexes whichever sequence is live;
// these two helpers are how every call site splits it back apart.
// Card pages an active order contributes. An order with no planet-scoped
// targets still gets one: drawCard() has a "ORDER HAS NO TARGETS" state for
// exactly that, and it is more honest than dropping to the idle screen that
// says there is no order at all.
static uint8_t orderPageCount(const HudModel &m) {
  if (!m.order.valid) return 0;
  return m.order.taskCount > 0 ? (uint8_t)m.order.taskCount : 1;
}

static uint8_t pageCount(const HudModel &m) {
  const uint8_t mo = orderPageCount(m);
  return mo > 0 ? mo : m.campaignCount;
}

// Whether page `idx` of the live sequence is a Major Order task card (vs. a
// campaign card, or nothing at all when idx is past the end).
static bool pageIsCard(const HudModel &m, uint8_t idx) {
  return idx < orderPageCount(m);
}

// --- Rates ------------------------------------------------------------------
//
// Everything the card says about *change* is measured here, by diffing the
// current poll against the sample the poll loop kept from the previous one.
// The API has no rate field; without two samples there is no number, and the
// card is expected to say so rather than print a zero.
struct CardRates {
  bool have = false;   // is there a usable pair of samples at all
  float pct = 0.0f;    // percentage points per hour on the leading bar
};

static CardRates cardRates(const HudModel &m, uint8_t idx, const OrderTask &t) {
  CardRates r;
  if (idx >= (uint8_t)kMaxOrderTasks) return r;
  const PlanetInfo &p = t.planet;
  const RateSample &h = m.history[idx];
  if (!p.valid || !h.valid || h.planetIndex != p.index) return r;

  if (p.event.active) {
    // Only against the same defence. When one event ends and another begins the
    // health pair restarts, and diffing across that would report a swing that
    // never happened.
    if (!h.haveEvent || h.eventEnd != p.event.endTime) return r;
    r.have = ratePerHour(p.event.defended(), p.observedAt, h.eventPct, h.at, r.pct);
  } else if (taskIsLiberation(t.taskType)) {
    r.have = ratePerHour(p.liberation, p.observedAt, h.libPct, h.at, r.pct);
  }
  return r;
}

// The %-per-hour a count-style objective is moving at, measured the same way
// cardRates() measures the planet ones — by diffing consecutive polls — but
// from the assignment payload's own progress rather than planet health, and so
// available even when the task's planet is not.
//
// Deliberately not folded into cardRates(): the stat strip's PUSH/REGEN columns
// describe the *planet*, and handing them an objective's rate would quote a
// push figure for a planet whose health is not moving at all.
static CardRates countRate(const HudModel &m, uint8_t idx, const OrderTask &t) {
  CardRates r;
  if (idx >= (uint8_t)kMaxOrderTasks || !taskIsCount(t)) return r;
  const RateSample &h = m.history[idx];
  if (!h.haveCount) return r;
  r.have = ratePerHour(taskPercent(t), m.lastSuccess, h.countPct, h.countAt, r.pct);
  return r;
}

// What a count-style task is counting, in the three places the card names it.
// Only the wording keys off the type code — whether a task gets a progress bar
// at all is decided by its goal (see taskIsCount) — so an objective type this
// build has never seen still renders real progress, just under a generic
// label. Getting the wording wrong costs a word; getting the bar wrong costs
// the whole card, which is the trade this split exists to make.
struct CountWords {
  const char *header;    // header row's type word
  const char *track;     // track caption, before the running total
  const char *headline;  // headline verb, after the percentage
};

static CountWords countWords(int32_t taskType) {
  switch (taskType) {
    case kTaskTypeExtract:    return {"EXTRACTION",  "EXTRACTED",  "EXTRACTED"};
    case kTaskTypeEradicate:  return {"ERADICATION", "ELIMINATED", "ELIMINATED"};
    case kTaskTypeOperations: return {"OPERATIONS",  "OPERATIONS", "COMPLETE"};
    default:                  return {"OBJECTIVE",   "PROGRESS",   "COMPLETE"};
  }
}

// Everything that, when it changes, warrants a full body repaint. The clocks,
// WiFi dot and footer are deliberately excluded — they update themselves
// through their own small sprites, and so are the MO card and the campaign
// card, which carry their own per-page signatures below because the carousel
// repaints just the active card on each advance rather than the whole frame.
static String contentSignature(const HudModel &m) {
  if (!m.haveData) return F("boot");
  String s;
  s.reserve(128);
  if (m.order.valid) {
    // An active order owns the screen, so nothing about the campaigns feed
    // can change what is drawn — it stays out of the signature entirely
    // rather than repainting the card every time the galaxy reshuffles.
    s = F("mo|");
    s += String(m.order.id);
    s += '|';
    s += String(m.order.taskCount);
    return s;
  }

  // War totals only feed the true idle screen's tiles (no order, no
  // campaigns either) — the campaign card's own SHARE stat also reads
  // m.war.playerCount, but that's tracked by campaignPageSignature() below
  // instead, so it doesn't have to force a full-frame repaint on its own.
  s = F("idle|");
  s += String(m.war.playerCount);
  s += '|';
  s += String(m.war.missionSuccessRate);
  s += '|';
  s += formatCompact(m.war.totalKills);

  // Which planets made the top N (and the count going to/from zero) has to
  // force a full repaint the way the order identity does. Per-campaign
  // liberation/player-count churn is deliberately left out — that's
  // campaignPageSignature()'s job, the same split contentSignature() and
  // targetSignature() already have for the MO card.
  s += F("|camp|");
  s += String(m.campaignCount);
  for (uint8_t i = 0; i < m.campaignCount; i++) {
    s += '|';
    s += String(m.campaigns[i].index);
  }
  return s;
}

// Everything the card draws, including which target it is. The two observation
// timestamps stand in for the derived rates: they are what those are computed
// from, and they move exactly when the rates do.
static String targetSignature(const HudModel &m, uint8_t idx) {
  const OrderTask *t = activeTask(m, idx);
  if (!t) return F("none");
  const PlanetInfo &p = t->planet;
  String s;
  s.reserve(160);
  s = String(idx);
  s += '/';
  s += String(m.order.taskCount);
  s += '|';
  s += m.order.title;
  s += '|';
  s += String(m.order.rewardAmount);
  s += '|';
  s += String(t->taskType);
  s += '|';
  s += String(t->planetIndex);
  s += '|';
  s += t->complete ? '1' : '0';
  s += '|';
  // A count task's progress moves every poll while its planet record sits
  // perfectly still, so without these the card would draw its first percentage
  // and then never repaint. Percent is carried at 1/100th resolution rather
  // than the raw total to keep the whole signature inside Arduino String's
  // 32-bit numeric formatting; a billion-kill goal still moves several hundred
  // of those steps between two five-minute polls.
  s += String((int)(taskPercent(*t) * 100.0f));
  s += '|';
  s += formatCompact(t->goal);
  s += '|';
  s += String((unsigned long)m.history[idx < kMaxOrderTasks ? idx : 0].countAt);
  s += '|';
  s += p.name;
  s += '|';
  s += p.sector;
  s += '|';
  s += p.biome;
  s += '|';
  s += p.owner;
  s += '|';
  s += String(p.playerCount);
  s += '|';
  s += String((int)(p.liberation * 100.0f));
  s += '|';
  s += String((unsigned long)p.observedAt);
  s += '|';
  s += String((unsigned long)m.history[idx < kMaxOrderTasks ? idx : 0].at);
  s += '|';
  for (uint8_t i = 0; i < p.hazardCount; i++) s += (char)('0' + (int)p.hazards[i]);
  s += '|';
  if (p.event.active) {
    s += p.event.faction;
    s += '@';
    s += String((unsigned long)p.event.endTime);
    s += '@';
    s += String((int)(p.event.defended() * 100.0f));
  }
  return s;
}

// The campaign-card equivalent of targetSignature() above: everything one
// campaign card draws, so an advance within the campaign half of the
// carousel only repaints the card, not the whole frame. Includes m.war.playerCount
// since the card's SHARE stat reads it directly.
static String campaignPageSignature(const HudModel &m, uint8_t idx) {
  if (idx >= m.campaignCount) return F("none");
  const PlanetInfo &p = m.campaigns[idx];
  String s;
  s.reserve(112);
  s = String(idx);
  s += '/';
  s += String(m.campaignCount);
  s += '|';
  s += p.name;
  s += '|';
  s += p.sector;
  s += '|';
  s += p.biome;
  s += '|';
  s += p.owner;
  s += '|';
  s += String(p.playerCount);
  s += '|';
  s += String((int)(p.liberation * 1000.0f));
  s += '|';
  s += String((unsigned long)p.observedAt);
  s += '|';
  s += String((unsigned long)m.campaignHistory[idx].at);
  s += '|';
  s += String(m.war.playerCount);
  return s;
}

// The status line for an objective that cannot honestly be shown as a
// percentage: defend tasks with nothing attacking them, and any type we don't
// recognise.
struct StatusLine {
  String text;
  uint16_t color;
};

static StatusLine objectiveStatus(const OrderTask &t) {
  if (taskIsCount(t)) {
    // A count task always has an honest percentage of its own, so it never
    // needs the neutral fallback below — and must not get it, since that
    // branch reads "OBJECTIVE COMPLETE" off a flag that only means "started".
    // Green once the goal is met, because the API keeps counting past it and
    // the percentage alone would sit at 100% looking unfinished.
    char buf[24];
    snprintf(buf, sizeof(buf), "%.1f%% %s", taskPercent(t), countWords(t.taskType).headline);
    return {String(buf), t.complete ? theme::green : theme::gold};
  }
  if (t.taskType == kTaskTypeDefend) {
    // Defence is pass/fail per task, and the API says which it is. The planet's
    // health only tells us whether an assault is in progress right now.
    if (t.complete) return {String(F("HELD")), theme::green};
    if (!t.planet.valid) return {String(F("AT RISK")), theme::gold};
    return t.planet.owner.equalsIgnoreCase("Humans")
               ? StatusLine{String(F("STANDING BY")), theme::gold}
               : StatusLine{String(F("LOST")), theme::red};
  }
  // Unknown objective kind: report the one thing the API is unambiguous about
  // rather than inventing a metric for it.
  return t.complete ? StatusLine{String(F("OBJECTIVE COMPLETE")), theme::green}
                    : StatusLine{String(F("IN PROGRESS")), theme::gold};
}

// Geometry of the three icon tiles the no-order screen uses, and of the two-up
// boxes on the WiFi setup screen.
static constexpr int16_t kTileW = (contentW - 2 * tileGap) / 3;  // 142
static constexpr int16_t kStatW = (contentW - statGap) / 2;      // 216
static constexpr int16_t kStatInsetX = 12;
static constexpr int16_t kStatValueDy = 21;
static constexpr int16_t kStatValueH = 20;

// How long each page of the unified carousel (MO task cards, then campaign
// cards) stays on screen. Long enough to read a card and glance away; short
// enough that even a full lap (task cards + up to 5 campaigns) comes round
// inside a normal look at the desk.
static const uint32_t kCarouselCycleMs = 7000;

// ---------------------------------------------------------------------------
//  Lifecycle
// ---------------------------------------------------------------------------

void HUDRenderer::begin() {
  _tft.init();
  // Rotation 1 turns the native 320x480 portrait panel into 480x320 landscape.
  // If the image is upside down for how the board sits on your desk, use 3.
  _tft.setRotation(1);
  _tft.fillScreen(theme::bg);

  // TFT_BL is driven by TFT_eSPI when TFT_BL is defined, but do it explicitly
  // so the backlight is on even if that define is later removed.
#ifdef TFT_BL
  pinMode(TFT_BL, OUTPUT);
  digitalWrite(TFT_BL, TFT_BACKLIGHT_ON);
#endif

  _pageSwitchMs = millis();
  invalidate();
}

void HUDRenderer::invalidate() {
  _chromeDrawn = false;
  _headerSig = "";
  _contentSig = "";
  _targetSig = "";
  _campaignSig = "";
  _clockSig = "";
  _footerSig = "";
  _wifiSig = -1;
}

// ---------------------------------------------------------------------------
//  Primitives
// ---------------------------------------------------------------------------

void HUDRenderer::textBox(int16_t x, int16_t y, int16_t w, int16_t h, uint16_t bg,
                          const GFXfont *font, uint16_t fg, uint8_t datum,
                          const String &s, int16_t inset) {
  TFT_eSprite spr(&_tft);
  spr.setColorDepth(16);
  if (spr.createSprite(w, h)) {
    spr.fillSprite(bg);
    spr.setFreeFont(font);
    spr.setTextColor(fg, bg);
    spr.setTextDatum(datum);
    int16_t ax, ay;
    datumAnchor(datum, w, h, ax, ay);
    if (datum == TL_DATUM || datum == ML_DATUM) ax += inset;
    if (datum == TR_DATUM || datum == MR_DATUM) ax -= inset;
    spr.drawString(s.c_str(), ax, ay);
    spr.pushSprite(x, y);
    spr.deleteSprite();
    return;
  }
  // Sprite allocation failed (heap pressure) — fall back to direct drawing.
  // Slight flicker, but never a blank region.
  _tft.fillRect(x, y, w, h, bg);
  _tft.setFreeFont(font);
  _tft.setTextColor(fg, bg);
  _tft.setTextDatum(datum);
  int16_t ax, ay;
  datumAnchor(datum, w, h, ax, ay);
  if (datum == TL_DATUM || datum == ML_DATUM) ax += inset;
  if (datum == TR_DATUM || datum == MR_DATUM) ax -= inset;
  _tft.drawString(s.c_str(), x + ax, y + ay);
}

// A biome plate, bilinearly scaled up into `dw x dh`. The plates are stored at
// half size (see tools/gen_biomes.py) precisely because this scaler exists, so
// the set fits in flash.
//
// `scrimW` darkens the plate from its left edge inward, ramping from
// `scrimMax` (0-255, blended toward black) back to the untouched artwork. The
// identity is set over that side of the plate, and a photograph is the one
// background text cannot be trusted against: the darkening is applied here,
// while each pixel is already being computed, rather than as a second pass.
void HUDRenderer::drawBiome(const uint16_t *src, int16_t sw, int16_t sh, int16_t dx,
                            int16_t dy, int16_t dw, int16_t dh, int16_t scrimW,
                            uint8_t scrimMax) {
  if (!src || dw <= 0 || dh <= 0) return;

  // pushImage() streams the buffer straight at the panel, which wants each
  // pixel MSB first; the words below are native-endian.
  const bool swap = _tft.getSwapBytes();
  _tft.setSwapBytes(true);

  uint16_t line[cardW];
  const int16_t span = dw > cardW ? cardW : dw;
  for (int16_t j = 0; j < dh; ++j) {
    const int32_t fy = srcCoord(j, sh, dh);
    const int32_t y0 = fy >> 8;
    const int32_t y1 = (y0 + 1 < sh) ? y0 + 1 : y0;
    const int ty = fy & 0xFF;
    const uint16_t *r0 = &src[y0 * sw];
    const uint16_t *r1 = &src[y1 * sw];

    for (int16_t i = 0; i < span; ++i) {
      const int32_t fx = srcCoord(i, sw, dw);
      const int32_t x0 = fx >> 8;
      const int32_t x1 = (x0 + 1 < sw) ? x0 + 1 : x0;
      const int tx = fx & 0xFF;
      uint16_t px =
          lerp565(lerp565(pgm_read_word(&r0[x0]), pgm_read_word(&r0[x1]), tx),
                  lerp565(pgm_read_word(&r1[x0]), pgm_read_word(&r1[x1]), tx),
                  ty);
      if (scrimW > 0 && i < scrimW) {
        const int t = (int)scrimMax * (scrimW - i) / scrimW;
        px = lerp565(px, 0x0000, t);  // toward black
      }
      line[i] = px;
    }
    _tft.pushImage(dx, dy + j, span, 1, line);
  }

  _tft.setSwapBytes(swap);
}

// Text straight onto whatever is already on the panel. textBox() fills its
// sprite with a flat colour, which would punch a hole in the artwork, so the
// identity set over the biome comes through here instead.
void HUDRenderer::drawOverText(int16_t x, int16_t y, int16_t h, const GFXfont *font,
                               uint16_t fg, const String &s) {
  if (h <= 0 || !s.length()) return;
  _tft.setFreeFont(font);
  _tft.setTextColor(fg);  // no bg colour == glyphs only, art shows through
  _tft.setTextDatum(ML_DATUM);
  _tft.drawString(s.c_str(), x, y + h / 2);
}

void HUDRenderer::drawRule(int16_t y) {
  _tft.drawFastHLine(padX, y, contentW, theme::goldDim);
}

int16_t HUDRenderer::tileX(int i) {
  return padX + i * (kTileW + tileGap);
}

void HUDRenderer::drawTile(int i, const uint8_t *icon, int16_t iw, int16_t ih,
                           const String &value, uint16_t valueColor) {
  const int16_t x = tileX(i);
  _tft.fillRect(x, tileY, kTileW, tileH, theme::panel);
  _tft.drawRect(x, tileY, kTileW, tileH, theme::goldDim);
  // The icon stands in for what used to be an ALL-CAPS label, so it is drawn
  // at label weight rather than value weight.
  _tft.drawBitmap(x + tileInsetX, tileY + tileIconDy, icon, iw, ih, theme::goldDim);

  // Drop a size rather than run off the edge of the tile.
  _tft.setFreeFont(FONT_VALUE);
  const GFXfont *font = (_tft.textWidth(value.c_str()) > kTileW - 2 * tileInsetX)
                            ? FONT_LABEL
                            : FONT_VALUE;
  textBox(x + 1, tileY + tileValueDy, kTileW - 2, tileValueH, theme::panel, font,
          valueColor, ML_DATUM, value, tileInsetX - 1);
}

void HUDRenderer::drawStatBox(int16_t x, int16_t y, int16_t w, int16_t h,
                              const String &label, const String &value,
                              uint16_t valueColor) {
  _tft.fillRect(x, y, w, h, theme::panel);
  _tft.drawRect(x, y, w, h, theme::goldDim);
  textBox(x + 1, y + 5, w - 2, 15, theme::panel, FONT_LABEL, theme::grey, ML_DATUM,
          label, kStatInsetX - 1);

  // Drop a size rather than run off the edge of the box (long values show up
  // in the WiFi-setup screen, and for very large player counts).
  _tft.setFreeFont(FONT_VALUE);
  const GFXfont *valueFont =
      (_tft.textWidth(value.c_str()) > w - 2 * kStatInsetX) ? FONT_LABEL : FONT_VALUE;
  textBox(x + 1, y + kStatValueDy, w - 2, kStatValueH, theme::panel, valueFont,
          valueColor, ML_DATUM, value, kStatInsetX - 1);
}

int16_t HUDRenderer::badgeWidth(const String &faction) {
  const String label = upper(faction.length() ? factionDisplayName(faction)
                                              : String("UNKNOWN"));
  const ColorIconRef ic = factionIcon(faction);

  _tft.setFreeFont(FONT_LABEL);
  int16_t w = _tft.textWidth(label.c_str()) + 2 * badgePadX;
  if (ic.px) w += ic.w + badgeIconGap;
  return w > badgeMaxW ? badgeMaxW : w;
}

void HUDRenderer::drawBadge(const String &faction, int16_t x, int16_t y, int16_t h) {
  const String label = upper(faction.length() ? factionDisplayName(faction)
                                              : String("UNKNOWN"));
  const uint16_t c = factionColor(faction);
  const ColorIconRef ic = factionIcon(faction);
  const int16_t w = badgeWidth(faction);

  _tft.fillRect(x, y, w, h, theme::bg);
  _tft.drawRect(x, y, w, h, c);

  if (ic.px) {
    // Icon then label, left-aligned as a pair. Since the badge is sized to
    // fit exactly, that reads as centred. textBox() clears the icon slot on
    // its way past, so the bitmap goes down afterwards.
    textBox(x + 1, y + 1, w - 2, h - 2, theme::bg, FONT_LABEL, c, ML_DATUM, label,
            badgePadX + ic.w + badgeIconGap - 1);
    // The icon arrays are plain uint16_t, so on a little-endian ESP32 they
    // reach the panel byte-reversed unless this is set -- which turns the
    // Automaton's salmon into a pale blue. headerBg never hit this because it
    // goes out through drawPixel(), a pixel at a time.
    _tft.setSwapBytes(true);
    _tft.pushImage(x + badgePadX, y + (h - ic.h) / 2, ic.w, ic.h, ic.px,
                   facicons::kTransparent);
    _tft.setSwapBytes(false);
  } else {
    textBox(x + 1, y + 1, w - 2, h - 2, theme::bg, FONT_LABEL, c, MC_DATUM, label);
  }
}

void HUDRenderer::drawTrack(int16_t y, int16_t h, float pct, uint16_t fill) {
  const float clamped = pct < 0.0f ? 0.0f : (pct > 100.0f ? 100.0f : pct);
  const int16_t fillW = (int16_t)((cardW - 2) * (clamped / 100.0f) + 0.5f);

  _tft.fillRect(cardX, y, cardW, h, theme::track);
  if (fillW > 0) _tft.fillRect(cardX + 1, y + 1, fillW, h - 2, fill);
  _tft.drawRect(cardX, y, cardW, h, theme::cardEdge);

  // Chevron cap riding the leading edge of the fill, once there is room for it
  // to sit inside the fill rather than straddle the track.
  if (fillW > icons::trendW + 6 && h >= icons::trendH + 2) {
    _tft.drawBitmap(cardX + 1 + fillW - icons::trendW - 3, y + (h - icons::trendH) / 2,
                    icons::trend, icons::trendW, icons::trendH, theme::text);
  }
}

// A track and the caption row above it: what the track measures on the left,
// its value and rate on the right. The readout sits above the bar rather than
// beside it because the track now runs the full content width — there is no
// column left over, and a bar that stops short to make one reads as a bar
// that is less full than it is.
void HUDRenderer::drawBarRow(int16_t capY, int16_t barY, int16_t barH,
                             const String &label, const String &readout,
                             uint16_t readoutColor, float pct, uint16_t fill) {
  textBox(cardX, capY, cardW / 2, barCapH, theme::bg, nullptr, theme::grey, ML_DATUM,
          label);
  textBox(cardX + cardW / 2, capY, cardW / 2, barCapH, theme::bg, nullptr, readoutColor,
          MR_DATUM, readout);
  drawTrack(barY, barH, pct, fill);
}

void HUDRenderer::drawIdleTrack(int16_t capY, int16_t barY, int16_t barH,
                                const String &label) {
  _tft.fillRect(cardX, capY, cardW, barCapH, theme::bg);
  _tft.fillRect(cardX, barY, cardW, barH, theme::track);
  _tft.drawRect(cardX, barY, cardW, barH, theme::cardEdge);
  textBox(cardX + 1, barY + 1, cardW - 2, barH - 2, theme::track, FONT_LABEL,
          theme::grey, MC_DATUM, label);
}

// ---------------------------------------------------------------------------
//  Chrome — outer frame, corner brackets, header row
// ---------------------------------------------------------------------------

void HUDRenderer::drawFrame() {
  const int16_t x0 = frameX, y0 = frameY;
  const int16_t x1 = frameX + frameW - 1, y1 = frameY + frameH - 1;

  _tft.drawRect(x0, y0, frameW, frameH, theme::goldDim);

  // Squared-off corner accents: two arms per corner, brighter and thicker
  // than the frame itself.
  const int16_t L = bracketLen, T = bracketThick;
  // top-left
  _tft.fillRect(x0, y0, L, T, theme::gold);
  _tft.fillRect(x0, y0, T, L, theme::gold);
  // top-right
  _tft.fillRect(x1 - L + 1, y0, L, T, theme::gold);
  _tft.fillRect(x1 - T + 1, y0, T, L, theme::gold);
  // bottom-left
  _tft.fillRect(x0, y1 - T + 1, L, T, theme::gold);
  _tft.fillRect(x0, y1 - L + 1, T, L, theme::gold);
  // bottom-right
  _tft.fillRect(x1 - L + 1, y1 - T + 1, L, T, theme::gold);
  _tft.fillRect(x1 - T + 1, y1 - L + 1, T, L, theme::gold);
}

int16_t HUDRenderer::drawLibcon(int16_t x, int16_t y, int16_t h, int8_t tier) {
  if (tier < 1 || tier > 5) return x;
  // Matches the community app's own LIBCON legend: 1 white, 2 red, 3 yellow,
  // 4 green, 5 blue.
  static const uint16_t kTierColor[6] = {
      0, theme::text, theme::red, theme::gold, theme::green, theme::blue,
  };
  const uint16_t fill = kTierColor[tier];
  // White and yellow/green fills need dark ink; red and blue read better with
  // light ink.
  const uint16_t ink = (tier == 2 || tier == 5) ? theme::text : theme::bg;
  const int16_t cy = y + (h - libconH) / 2;
  _tft.fillRect(x, cy, libconW, libconH, fill);
  _tft.drawRect(x, cy, libconW, libconH, theme::bg);
  char label[12];
  snprintf(label, sizeof(label), "LIBCON %d", tier);
  textBox(x, cy, libconW, libconH, fill, FONT_LABEL, ink, MC_DATUM, label);
  return x + libconW;
}

// The header row, shared by every screen: what kind of objective this is, the
// LIBCON chip beside it, the carousel pips, and (from drawWifi) the link
// state at the right. The chip moved up here from the footer when the cards
// were rebuilt around the artwork -- the footer row it used to share with the
// sync line no longer had the clearance, and the reading belongs next to the
// objective type it qualifies anyway.
void HUDRenderer::drawStatusHeader(const String &title, int8_t tier, uint8_t pages,
                                   uint8_t page) {
  const String label = title.length() ? title : String(F("SUPER EARTH"));

  _tft.setFreeFont(FONT_LABEL);
  const int16_t labelW = _tft.textWidth(label.c_str());
  // Cleared across the whole row up to the WiFi slot, not to the label's own
  // width. Everything drawn after this -- the chip, the pips -- is positioned
  // off labelW, so a long type word giving way to a short one ("EXTERMINATION"
  // to "DEFENSE" as the carousel advances) slides them left and would strand
  // the previous frame's copies to the right of the new ones. A fixed 200 was
  // wide enough for the label's own tail and nothing else, which was invisible
  // while this row was only ever painted onto a freshly-cleared screen.
  textBox(padX, headerY, contentW - wifiSlotW, headerH, theme::bg, FONT_LABEL,
          theme::gold, ML_DATUM, label);

  int16_t x = padX + labelW + libconGapX;
  if (tier >= 1 && tier <= 5) x = drawLibcon(x, headerY, headerH, tier);

  // Carousel position, just past the chip. Only drawn when there is more than
  // one page -- a single dot says nothing a blank row does not.
  //
  // The active pip is a filled square at full size against hollow outlines two
  // pixels smaller all round, rather than same-size filled-vs-hollow: at this
  // size the fill alone was a difference you had to go looking for from a desk
  // away, and the one thing this row exists to say is which page you are on.
  if (pages > 1) {
    x += pipRowGap;
    for (uint8_t i = 0; i < pages; i++, x += pipS + pipGap) {
      if (i == page) {
        _tft.fillRect(x, headerY + (headerH - pipS) / 2, pipS, pipS, theme::gold);
      } else {
        const int16_t s = pipS - 2 * pipDimInset;
        _tft.drawRect(x + pipDimInset, headerY + (headerH - s) / 2, s, s,
                      theme::goldDim);
      }
    }
  }

  drawRule(rule1Y);
}

// What the header row is currently saying, and the repaint that keeps it true.
//
// Split out of drawBody() because drawBody() is not what runs when the
// carousel advances: a page step inside one Major Order leaves
// contentSignature() unchanged, so update() repaints the card alone and this
// row kept whatever it was painted with at the last full repaint. The pips
// therefore never moved on hardware, and the objective-type word beside them
// was equally stale -- an advance from a liberation target to a defence one
// left "LIBERATION" over a defence card. Signature-guarded so calling it every
// frame costs one string compare.
void HUDRenderer::drawHeader(const HudModel &m) {
  const uint8_t pages = pageCount(m);
  const bool cardPage = pageIsCard(m, _pageIdx);

  // The type word is what changes -- an order card names its objective, a
  // campaign card is always a liberation, and the screens with no card keep
  // the plain strip.
  String type;
  if (m.haveData) {
    if (cardPage) {
      const OrderTask *t = activeTask(m, _pageIdx);
      const bool defending =
          t && ((t->taskType == kTaskTypeDefend) || t->planet.event.active);
      const bool liberating = t && taskIsLiberation(t->taskType);
      // Same precedence the card body uses: a count objective names itself
      // even when its planet happens to be under attack, because the count is
      // what the order is asking for.
      if (t && taskIsCount(*t)) type = countWords(t->taskType).header;
      else type = defending ? F("DEFENSE") : (liberating ? F("LIBERATION") : F("OBJECTIVE"));
    } else if (pages > 0) {
      type = F("LIBERATION");
    }
  }

  const int8_t tier = m.haveData ? libconTier(m) : 0;
  const String sig =
      type + "|" + String((int)tier) + "|" + String((int)pages) + "|" + String((int)_pageIdx);
  if (sig == _headerSig) return;
  _headerSig = sig;

  drawStatusHeader(type, tier, pages, _pageIdx);
}

void HUDRenderer::drawWifi(bool up) {
  const int8_t sig = up ? 1 : 0;
  if (sig == _wifiSig) return;
  _wifiSig = sig;

  const uint16_t c = up ? theme::green : theme::red;
  const int16_t dotR = footDotR;
  const int16_t dotCx = contentR - dotR;
  const int16_t cy = headerY + headerH / 2;
  const char *label = up ? "WIFI" : "OFFLINE";

  // Label right-aligned just left of the dot. The slot width is shared with
  // drawStatusHeader(), which clears the rest of the row up to its left edge.
  textBox(contentR - wifiSlotW, headerY, wifiSlotW - (2 * dotR + 6), headerH,
          theme::bg, FONT_LABEL, c, MR_DATUM, String(label));

  _tft.fillRect(dotCx - dotR, cy - dotR, 2 * dotR + 1, 2 * dotR + 1, theme::bg);
  _tft.fillCircle(dotCx, cy, dotR, c);
}

// ---------------------------------------------------------------------------
//  Cards
// ---------------------------------------------------------------------------

// "62.0%   +2.1% / h", or the same with "--" where two polls have not yet
// produced a rate. Both card types put this at the right of a track's caption
// row, so the formatting lives in one place.
static String rateReadout(float pct, bool haveRate, float rate) {
  String s = String(pct, 1);
  s += F("%   ");
  s += haveRate ? formatRate(rate) : String(F("--"));
  return s;
}

// The faction insignia alone, on a dark disc, top-right of the art band.
//
// There is no label: the badge's text lived in a row this design no longer
// has, and the three marks are distinct enough to carry it. SEAF has no
// insignia that survives reduction to this size (see factionIcon), so a
// human-held planet simply shows no mark rather than a blob.
void HUDRenderer::drawFactionMark(const String &faction) {
  const ColorIconRef ic = factionIcon(faction);
  if (!ic.px) return;

  const int16_t r = ic.w / 2 + markPad;
  const int16_t cx = cardX + cardW - markInset - r;
  const int16_t cy = artY + markInset + r;

  _tft.fillCircle(cx, cy, r, theme::bg);
  _tft.drawCircle(cx, cy, r, theme::cardEdge);
  // The icon arrays are plain uint16_t, so on a little-endian ESP32 they reach
  // the panel byte-reversed unless this is set -- which turns the Automaton's
  // salmon into a pale blue.
  _tft.setSwapBytes(true);
  _tft.pushImage(cx - ic.w / 2, cy - ic.h / 2, ic.w, ic.h, ic.px,
                 facicons::kTransparent);
  _tft.setSwapBytes(false);
}

// The art band: the biome plate with the planet's identity set over it. Both
// card types open with this, which is what makes the carousel hold still as
// it advances -- only the headline stat and what sits below the band differ.
void HUDRenderer::drawArtBand(const PlanetInfo &p, int16_t h, const String &headline,
                              uint16_t headlineColor, const String &orderTitle,
                              const String &fallbackName) {
  const int8_t bi = biomeFromName(p.biome);
  const uint16_t *plate =
      (uint16_t *)pgm_read_ptr(&biomes::table[bi < 0 || bi >= biomes::kCount
                                                  ? kBiomeUnknown
                                                  : bi]);
  drawBiome(plate, biomes::kW, biomes::kH, cardX, artY, cardW, h, artScrimW,
            artScrimMax);
  _tft.drawRect(cardX, artY, cardW, h, theme::cardEdge);

  const int16_t tx = cardX + artPad;
  // Everything left of the faction mark's disc is the identity's to use.
  const int16_t availW =
      cardW - artPad - markInset - (facicons::automatonW + 2 * markPad) - 12;

  // Anton is condensed, but planet names run to "ANGEL'S VENTURE"; drop a cut
  // and then trim rather than run under the mark.
  String name = upper(p.valid ? p.name
                              : (fallbackName.length() ? fallbackName
                                                       : String(F("UNKNOWN"))));
  const GFXfont *nameFont = FONT_HEADLINE;
  _tft.setFreeFont(nameFont);
  if (_tft.textWidth(name.c_str()) > availW) {
    nameFont = FONT_HEADLINE_SM;
    _tft.setFreeFont(nameFont);
  }
  while (name.length() > 1 && _tft.textWidth(name.c_str()) > availW) {
    name.remove(name.length() - 1);
  }
  drawOverText(tx, artY + artNameDy, artNameH, nameFont, theme::text, name);

  const String sector = sectorLabel(p.sector);
  if (sector.length()) {
    drawOverText(tx, artY + artSectorDy, artSectorH, FONT_BODY, theme::grey, sector);
  }
  if (headline.length()) {
    drawOverText(tx, artY + artStatDy, artStatH, FONT_VALUE, headlineColor, headline);
  }

  // The order's own name, under the headline. Trimmed against the clock
  // plate's left edge so a long title stops rather than running under it.
  if (orderTitle.length()) {
    String shown = orderTitle;
    const int16_t stopAt = cardX + cardW - plateInset - plateW - 10;
    _tft.setFreeFont(FONT_LABEL);
    while (shown.length() > 1 && tx + _tft.textWidth(shown.c_str()) > stopAt) {
      shown.remove(shown.length() - 1);
    }
    drawOverText(tx, artY + artTitleDy, artTitleH, FONT_LABEL, theme::gold, shown);
  }

  drawFactionMark(p.owner);
}

// The stat strip both cards close with: share of the galaxy's divers, the
// head-count here, the players' push, and the enemy's regen. The last two are
// the halves of the net rate the track above is moving at -- push minus regen
// -- which is why they sit together rather than beside their own bars.
//
// That pair only exists when the track above *is* a planet's own liberation or
// defence. A count-style objective is measured against the order's goal
// instead: nothing pushes the count but the war, and the planet's regen (when
// it even has a planet) is not what the bar is moving on. Both columns were
// therefore structurally "--" on every count card ever drawn -- not
// occasionally, always -- so `eta` replaces them with the one forward-looking
// figure that payload does support, and the row closes at three columns.
//
// The band is cleared as a unit first because the column count is no longer
// fixed: a carousel step from a liberation target to a count one repaints the
// card without repainting the screen, and four columns' worth of separators
// and captions would otherwise show through three columns' worth of paint.
void HUDRenderer::drawStrip(const HudModel &m, const PlanetInfo &p, bool haveRate,
                            float rate, uint16_t accent, const String &eta,
                            bool countStyle) {
  const float regenPctPerHour =
      p.maxHealth > 0 ? p.regenPerSecond * 3600.0f * 100.0f / (float)p.maxHealth : 0.0f;
  const float pushPctPerHour = (haveRate ? rate : 0.0f) + regenPctPerHour;

  char share[12], here[16], push[16], regen[16];
  // Galaxy-wide count is a separate reading taken at a separate moment, so it
  // can legitimately be smaller than this planet's. Clamp rather than print an
  // arithmetically-correct 200050%.
  const uint32_t galaxy = m.war.valid ? m.war.playerCount : 0;
  uint32_t sharePct = galaxy ? (uint32_t)((p.playerCount * 100ULL) / galaxy) : 0U;
  if (sharePct > 100) sharePct = 100;
  // Every column here is read off the planet record, so without one they are
  // all unknown rather than zero — and a count-style card is drawn from the
  // assignment payload alone, which makes "no planet, real progress" a routine
  // state rather than a broken one. "0 DIVERS / 0.00% REGEN" under a bar that
  // is visibly moving reads as a contradiction; "--" is what the PUSH column
  // has always said when it had nothing to report, so say it four times over.
  if (p.valid) {
    snprintf(share, sizeof(share), "%u%%", (unsigned)sharePct);
    snprintf(here, sizeof(here), "%s", formatCount(p.playerCount).c_str());
    if (haveRate) snprintf(push, sizeof(push), "%.3f%%", pushPctPerHour);
    else          snprintf(push, sizeof(push), "--");
    snprintf(regen, sizeof(regen), "%.2f%%", regenPctPerHour);
  } else {
    snprintf(share, sizeof(share), "--");
    snprintf(here, sizeof(here), "--");
    snprintf(push, sizeof(push), "--");
    snprintf(regen, sizeof(regen), "--");
  }

  // "/H" on the two rates because they are per-hour and the values carry only
  // a percent sign; without it "2.593%" reads as a position, not a speed.
  struct Col { const char *cap; String v; uint16_t c; };
  Col cols[stripCols];
  uint8_t n = 0;
  cols[n++] = {"SHARE", share, theme::gold};
  cols[n++] = {"DIVERS", here, theme::text};
  if (countStyle) {
    cols[n++] = {"ETA", eta.length() ? eta : String(F("--")), theme::blue};
  } else {
    cols[n++] = {"PUSH /H", push, theme::blue};
    cols[n++] = {"REGEN /H", regen, accent};
  }

  const int16_t stripH = (stripValY + stripValH) - stripCapY;
  _tft.fillRect(padX, stripCapY, contentW, stripH, theme::bg);

  const int16_t colW = contentW / n;
  for (uint8_t i = 0; i < n; i++) {
    const int16_t x = padX + i * colW;
    // nullptr font == TFT_eSPI's built-in 6x8 GLCD face; see setFreeFont().
    textBox(x, stripCapY, colW - 6, stripCapH, theme::bg, nullptr, theme::grey,
            ML_DATUM, cols[i].cap);
    textBox(x, stripValY, colW - 6, stripValH, theme::bg, FONT_LABEL, cols[i].c,
            ML_DATUM, cols[i].v);
    if (i) _tft.drawFastVLine(x - 4, stripCapY + 2, stripH - 4, theme::cardEdge);
  }
}

void HUDRenderer::drawCard(const HudModel &m) {
  _targetSig = targetSignature(m, _pageIdx);

  const OrderTask *t = activeTask(m, _pageIdx);
  if (!t) {
    _tft.fillRect(cardX, artY, cardW, (stripValY + stripValH) - artY, theme::bg);
    textBox(cardX, artY + 50, cardW, 34, theme::bg, FONT_VALUE, theme::grey, MC_DATUM,
            F("ORDER HAS NO TARGETS"));
    _clockSig = "";
    return;
  }

  const PlanetInfo &p = t->planet;
  // Whoever is attacking sets the card's accent; with nobody attacking it
  // falls back to the HUD's own gold.
  const uint16_t accent =
      p.event.active ? factionAccent(p.event.faction) : theme::gold;
  const CardRates r = cardRates(m, _pageIdx, *t);

  const CardRates cr = countRate(m, _pageIdx, *t);

  // The headline is whatever this objective is honestly measured by: a count
  // by how far through its own goal it is, a defence by how much of it is
  // held, a liberation by how much is taken, and anything else by the one
  // thing the API is unambiguous about.
  //
  // The count case is tested first, and without consulting the planet at all.
  // Its progress comes from the assignment payload, so it is the one figure
  // still available when /planets/{index} 404s — the state that used to leave
  // this card reading "UNKNOWN / OBJECTIVE COMPLETE / AWAITING TELEMETRY" for
  // an objective that was in fact a fifth of the way in. It also outranks a
  // defence running on the same planet: the order asks for the count, and
  // that is what the card is reporting against.
  String headline;
  uint16_t headlineColor = theme::gold;
  char buf[32];
  if (taskIsCount(*t)) {
    const StatusLine st = objectiveStatus(*t);
    headline = st.text;
    headlineColor = st.color;
  } else if (p.valid && p.event.active) {
    snprintf(buf, sizeof(buf), "%.0f%% DEFENDED", p.event.defended());
    headline = buf;
  } else if (p.valid && taskIsLiberation(t->taskType)) {
    snprintf(buf, sizeof(buf), "%.1f%% LIBERATED", p.liberation);
    headline = buf;
  } else {
    const StatusLine st = objectiveStatus(*t);
    headline = st.text;
    headlineColor = st.color;
  }

  // With no planet record there is still something true to put in the identity
  // line. Naming the index says which planet the API has no entry for, which
  // is a fact; "UNKNOWN" reads as a fault in the device. A count task with no
  // planet slot at all is genuinely galaxy-wide and says so.
  String fallbackName;
  if (!p.valid) {
    if (t->planetIndex >= 0) fallbackName = String(F("PLANET ")) + String(t->planetIndex);
    else if (taskIsCount(*t)) fallbackName = F("GALAXY-WIDE");
  }

  drawArtBand(p, artOrderH, headline, headlineColor, upper(m.order.title), fallbackName);

  // Cleared as one band whichever way it is about to be filled: a one-track
  // card following a two-track one would otherwise leave the second bar
  // stranded on screen, and the two layouts do not share row positions.
  _tft.fillRect(cardX, orderCap1Y, cardW, orderBandEnd - orderCap1Y, theme::bg);

  if (taskIsCount(*t)) {
    // The liberation bar's language, against the task's own goal instead of a
    // planet's health: caption names what is being counted and carries the
    // running total, readout gives the percentage and the rate it is moving
    // at. formatCompact keeps "241.2M / 1.3B" inside the caption's half-width
    // where the raw figures would run past it by a mile.
    //
    // Drawn from the assignment payload alone — no p.valid test anywhere in
    // here — because a planet lookup that fails must cost the card its
    // artwork and stat strip, not its progress.
    const CountWords w = countWords(t->taskType);
    const float pct = taskPercent(*t);
    String caption = String(w.track) + F("  ") + formatCompact(t->progress) +
                     F(" / ") + formatCompact(t->goal);
    drawBarRow(orderSoloCapY, orderSoloBarY, campBarH, caption,
               rateReadout(pct, cr.have, cr.pct),
               t->complete ? theme::green : theme::blue, pct,
               t->complete ? theme::green : theme::blue);
  } else if (p.valid && p.event.active) {
    // A defence is a tug of war over one bar: our share and theirs. The API
    // publishes only the pair, so the second bar is the first's complement —
    // and its rate is therefore the mirror of the first's, not a second
    // independent measurement.
    const float held = p.event.defended();
    drawBarRow(orderCap1Y, orderBar1Y, orderBarH, String(F("SEAF HOLDING")),
               rateReadout(held, r.have, r.pct), theme::blue, held, theme::blue);
    drawBarRow(orderCap2Y, orderBar2Y, orderBarH,
               upper(factionDisplayName(p.event.faction)) + String(F(" PUSH")),
               rateReadout(100.0f - held, r.have, -r.pct), accent, 100.0f - held,
               accent);
  } else if (p.valid && taskIsLiberation(t->taskType)) {
    drawBarRow(orderSoloCapY, orderSoloBarY, campBarH, String(F("LIBERATION")),
               rateReadout(p.liberation, r.have, r.pct), theme::blue, p.liberation,
               theme::blue);
  } else {
    // A defend objective with nothing attacking it has no progress to show:
    // the planet sits at full health, which is not "0% done". Now a genuine
    // last resort — every objective that carries a goal of its own is drawn as
    // a real bar above, so reaching here means the task offered no measurable
    // progress at all, not merely that it was an unfamiliar type.
    drawIdleTrack(orderSoloCapY, orderSoloBarY, campBarH,
                  p.valid ? String(F("NO ASSAULT IN PROGRESS"))
                          : String(F("AWAITING TELEMETRY")));
  }

  // A count objective's strip trades PUSH/REGEN for how long the goal is still
  // away at the rate the count is actually moving -- which is the question the
  // card is being asked, since the order's own clock is on the plate above it.
  // Measured off the same two samples the bar's %/h is, so it says "--" in the
  // same places that does rather than extrapolating from one poll.
  String eta;
  if (taskIsCount(*t)) {
    const float remain = 100.0f - taskPercent(*t);
    if (t->complete || remain <= 0.0f) {
      eta = F("MET");
    } else if (cr.have && cr.pct > 0.0f) {
      const double hours = (double)remain / cr.pct;
      // Past three months the figure stops being a forecast and starts being
      // arithmetic about a rate nobody expects to hold; say so rather than
      // print a date in the next war.
      eta = hours > 99.0 * 24.0 ? String(F("> 99d"))
                                : formatDuration((int64_t)(hours * 3600.0));
    }
  }

  drawStrip(m, p, r.have, r.pct, accent, eta, taskIsCount(*t));
  _clockSig = "";  // the plate went down with the art
}

// The order's clock and title, on their own filled plate at the foot of the
// art. The plate exists because the clock ticks: text painted straight onto
// the photograph could not be repainted without regenerating the artwork
// underneath it every second.
void HUDRenderer::drawCardClocks(const HudModel &m, time_t nowUtc) {
  if (!_cardMode) return;

  // 1.6e9 ~= 2020-09; anything below that means NTP hasn't synced yet and a
  // countdown would be nonsense.
  const bool clockOk = nowUtc > 1600000000;
  const OrderTask *t = activeTask(m, _pageIdx);

  // A running defence has its own deadline, and while one is up that is the
  // clock that matters; otherwise the order's own expiry is the only one
  // there is.
  String label = F("ORDER ENDS");
  int64_t until = (int64_t)m.order.expiration;
  if (t && t->planet.event.active && t->planet.event.endTime > 0) {
    label = F("VICTORY IN");
    until = (int64_t)t->planet.event.endTime;
  }
  const String clock = (until > 0 && clockOk)
                           ? formatDuration(until - (int64_t)nowUtc)
                           : String(F("--"));

  const String sig = label + "|" + clock;
  if (sig == _clockSig) return;
  _clockSig = sig;

  const int16_t plateH = plateLabelH + plateClockH + 2 * platePadY;
  const int16_t px = cardX + cardW - plateInset - plateW;
  const int16_t py = artY + artOrderH - plateInset - plateH;

  _tft.fillRect(px, py, plateW, plateH, theme::bg);
  _tft.drawRect(px, py, plateW, plateH, theme::cardEdge);

  // nullptr font == the built-in 6x8 GLCD face; the label is a caption, and
  // setting it any larger is what made the one-line form too wide to fit.
  textBox(px + 1, py + platePadY, plateW - 2, plateLabelH, theme::bg, nullptr,
          theme::grey, MC_DATUM, label);
  textBox(px + 1, py + platePadY + plateLabelH, plateW - 2, plateClockH, theme::bg,
          FONT_LABEL, theme::text, MC_DATUM, clock);
}

// ---------------------------------------------------------------------------
//  Body
// ---------------------------------------------------------------------------

void HUDRenderer::drawBody(const HudModel &m, time_t nowUtc) {
  // Clear the whole frame interior, then repaint the frame, since the corner
  // brackets are thicker than the 1px border we left standing.
  _tft.fillRect(frameX + 1, frameY + 1, frameW - 2, frameH - 2, theme::bg);
  drawFrame();

  _cardMode = pageIsCard(m, _pageIdx);
  const bool onCampaign = !_cardMode && pageCount(m) > 0;

  // Every screen wears the same header row now: what it is showing, the
  // LIBCON reading, and where in the carousel it sits. Forced through rather
  // than left to its signature: the row was just cleared with the rest of the
  // frame, whatever it happens to say next.
  _headerSig = "";
  drawHeader(m);
  _wifiSig = -1;  // the repaint wiped the dot

  if (!m.haveData) {
    _tft.drawBitmap(padX + (contentW - icons::emblemLargeW) / 2, 96,
                    icons::emblemLarge, icons::emblemLargeW, icons::emblemLargeH,
                    theme::goldDim);
    textBox(padX, 150, contentW, 34, theme::bg, FONT_DISPLAY, theme::gold, MC_DATUM,
            F("ESTABLISHING UPLINK"));
    drawRule(rule3Y);
  } else if (_cardMode) {
    _targetSig = "";
    drawCard(m);
  } else if (onCampaign) {
    // Campaign pages only exist when no order is active, so the page index is
    // the campaign index directly -- there are no card pages ahead of them.
    _campaignSig = "";
    const uint8_t ci = _pageIdx;
    drawCampaignBody(m, m.campaigns[ci], m.campaignHistory[ci]);
  } else {
    drawIdleBody(m);
    drawRule(rule3Y);
  }

  // Force the self-updating regions to repaint into the freshly cleared area.
  _clockSig = "";
  _footerSig = "";
  if (_cardMode) drawCardClocks(m, nowUtc);
  drawFooter(m, nowUtc);
}

void HUDRenderer::drawCampaignBody(const HudModel &m, const PlanetInfo &p,
                                   const RateSample &h) {
  const uint16_t accent = factionAccent(p.owner);

  float rate = 0.0f;
  const bool haveRate =
      h.valid && ratePerHour(p.liberation, p.observedAt, h.libPct, h.at, rate);

  // Four decimals because a campaign moves slowly enough that fewer would sit
  // unchanged between polls and read as a frozen screen.
  char headline[32];
  snprintf(headline, sizeof(headline), "%.4f%% LIBERATED", p.liberation);
  drawArtBand(p, artCampH, headline, theme::gold);

  drawBarRow(campCapY, campBarY, campBarH, String(F("LIBERATION")),
             rateReadout(p.liberation, haveRate, rate), accent, p.liberation, accent);

  drawStrip(m, p, haveRate, rate, accent);
}

void HUDRenderer::drawIdleBody(const HudModel &m) {
  // With no order to show, the emblem becomes the centrepiece and the galactic
  // war totals take over the tiles.
  _tft.drawBitmap(padX + (contentW - icons::emblemLargeW) / 2, 92, icons::emblemLarge,
                  icons::emblemLargeW, icons::emblemLargeH, theme::goldDim);
  // At 18pt this line is 463px, wider than the 440px content column, so it is
  // set at value size.
  textBox(padX, 146, contentW, 28, theme::bg, FONT_VALUE, theme::gold, MC_DATUM,
          F("NO ACTIVE MAJOR ORDER"));

  drawTile(0, icons::divers, icons::diversW, icons::diversH,
           m.war.valid ? formatCompact(m.war.playerCount) : String("--"), theme::gold);
  drawTile(1, icons::skull, icons::skullW, icons::skullH,
           m.war.valid ? formatCompact(m.war.totalKills) : String("--"), theme::gold);
  drawTile(2, icons::check, icons::checkW, icons::checkH,
           m.war.valid ? String(m.war.missionSuccessRate) + "%" : String("--"),
           theme::gold);
}

// A clock face at caption scale: a ring with an hour and a minute hand. Small
// enough to sit inside the footer row beside a 6x8 time, and drawn from
// primitives rather than added to hud_icons.h -- the existing clock bitmap is
// 24px, three times this row's budget, and the image is at 96% of its flash
// slot. The hands are drawn as plain runs because at r=5 an angled line is
// three pixels of noise; up and right reads as "a clock" and nothing else.
static void drawClockGlyph(TFT_eSPI &tft, int16_t cx, int16_t cy, uint16_t c) {
  tft.drawCircle(cx, cy, syncGlyphR, c);
  tft.drawFastVLine(cx, cy - 3, 4, c);
  tft.drawFastHLine(cx, cy, 3, c);
}

// The footer row: the order's reward at the left, the sync clock at the right.
//
// It used to open with the head-count on the planet being shown, which was the
// same number the strip's DIVERS column had already given a caption to two
// rows above -- one planet's divers, printed twice on one screen. The strip is
// where it belongs (it sits beside SHARE, which is that count over the
// galaxy's), so this row lost it.
//
// What is left is deliberately not repacked to fill the width. The reward is
// the row's one headline and takes the left edge and FONT_VALUE for it; the
// sync time is a staleness indicator, not a reading anyone comes to the panel
// for, so it shrank to a glyph and a 6x8 HH:MM at the right. The space between
// them stays empty on purpose: everything else this row could carry is either
// already on the card or would be filler.
void HUDRenderer::drawFooter(const HudModel &m, time_t nowUtc) {
  String synced;
  if (!m.haveData) {
    synced = F("NO DATA");
  } else {
    char t[8] = "--:--";
    if (m.lastSuccess > 0) {
      // Shift the epoch, then read it back as if it were UTC: that yields
      // local wall-clock time without depending on a TZ database being
      // present, and without touching the countdowns, which are durations.
      struct tm tmv;
      time_t ls = m.lastSuccess + (time_t)m.utcOffsetMin * 60;
      gmtime_r(&ls, &tmv);
      snprintf(t, sizeof(t), "%02d:%02d", tmv.tm_hour, tmv.tm_min);
    }
    // "SYNCED" is gone: the word cost the row 150px of body text to qualify a
    // clock reading that is only interesting when it is old. "STALE" stays,
    // because that is the case where the number above it cannot be trusted and
    // the row has one line in which to say so — at caption size it costs 36px,
    // not 150, and colour alone at 6x8 is a thin thing to hang it on.
    synced = m.stale ? String(F("STALE ")) + t : String(t);
  }

  // Reward, as a medal icon and a bare number — "REWARD n MEDALS" spelled out
  // was the single wordiest thing on the HUD for one integer of information.
  String reward;
  if (m.haveData && m.order.valid && m.order.rewardAmount > 0) {
    reward = String(m.order.rewardAmount);
  }

  const String sig = synced + "|" + reward + "|" + (m.stale ? "1" : "0") + "|" +
                     (m.touchUncalibrated ? "1" : "0");
  if (sig == _footerSig) return;
  _footerSig = sig;

  const int16_t y = footerY;
  const int16_t h = footerH;
  // Amber rather than the goldMute this line used to fade to. Muting was
  // legible while it was 150px of body text; shrunk to a 6x8 caption it made
  // the one state worth noticing the hardest thing on the panel to read, which
  // is backwards. Stale data is a caution, so it takes the caution colour.
  const uint16_t syncColor = m.stale ? theme::amber : theme::grey;

  // --- left: the order's reward -------------------------------------------
  // Cleared to a fixed width rather than the number's own: an order paying 45
  // following one that paid 120 would otherwise leave the hundreds digit
  // standing. The box holds four digits, well past any reward issued so far.
  const int16_t rewardW = icons::medalW + footerIconGap + kRewardBoxW;
  textBox(cardX, y, rewardW, h, theme::bg, FONT_VALUE, theme::gold, ML_DATUM,
          reward, icons::medalW + footerIconGap);
  if (reward.length()) {
    _tft.drawBitmap(cardX, y + (h - icons::medalH) / 2, icons::medal, icons::medalW,
                    icons::medalH, theme::gold);
  }

  // --- middle: the uncalibrated-touch hint ---------------------------------
  // Painted unconditionally, with an empty string when there is nothing to say,
  // so the frame calibration succeeds on is the frame the line disappears in --
  // the box clears itself and, because calibrated() never goes back to false on
  // its own, never comes back. theme::grey and the 6x8 face: the same weight as
  // the sync time across from it, which is the right of way for a caption that
  // is only addressed to a unit nobody has set up yet. Deliberately not
  // goldMute -- gold at this size is what the reward beside it is using, and
  // muted gold on this background was already found to be the least legible
  // thing on the panel when the footer was reworked.
  const String hint =
      m.touchUncalibrated ? String(F("HOLD SCREEN AT POWER-ON TO CALIBRATE")) : String();
  textBox(kHintX, y, kHintW, h, theme::bg, nullptr, theme::grey, MC_DATUM, hint);

  // --- right: last sync ----------------------------------------------------
  // The link state moved to the header row with the LIBCON chip, so this row
  // is the sync line's alone and it can run to the content edge.
  textBox(contentR - syncBoxW, y, syncBoxW, h, theme::bg, nullptr, syncColor,
          MR_DATUM, synced);
  // nullptr font == the built-in 6x8 GLCD face, the same one the box above was
  // set in; the glyph rides just left of whatever width that came to, and sits
  // inside the box's own clear so the previous frame's copy goes with it.
  _tft.setFreeFont(nullptr);
  const int16_t timeW = _tft.textWidth(synced.c_str());
  drawClockGlyph(_tft, contentR - timeW - syncGap - syncGlyphR, y + h / 2, syncColor);

  (void)nowUtc;
}

// ---------------------------------------------------------------------------
//  Public entry points
// ---------------------------------------------------------------------------

void HUDRenderer::updateCarousel(const HudModel &m) {
  const uint8_t count = pageCount(m);
  if (count <= 1) {
    // Nothing to cycle. Keep the stamp fresh so the first multi-page state to
    // arrive gets a full dwell before it advances.
    _pageIdx = 0;
    _pageSwitchMs = millis();
    return;
  }
  if (_pageIdx >= count) _pageIdx = 0;  // data set shrank under us

  const uint32_t nowMs = millis();
  if ((uint32_t)(nowMs - _pageSwitchMs) >= kCarouselCycleMs) {
    _pageIdx = (uint8_t)((_pageIdx + 1) % count);
    _pageSwitchMs = nowMs;
  }
}

void HUDRenderer::advancePage(const HudModel &m, int8_t delta) {
  const uint8_t count = pageCount(m);
  if (count == 0) return;

  // Wrap in both directions. `delta` is +/-1 from a swipe, but the modulo is
  // written to survive any value rather than assuming that.
  int16_t next = (int16_t)_pageIdx + delta;
  while (next < 0) next += count;
  _pageIdx = (uint8_t)(next % count);

  // Restarting the dwell is the whole point of doing this here rather than
  // poking _pageIdx from outside: a manual advance that still expired on the
  // old schedule would page again a moment later, undoing the thing that was
  // just asked for. Cody's explicit decision is that the timer stays as a
  // fallback -- so it keeps running, it just starts counting again from now.
  _pageSwitchMs = millis();
}

void HUDRenderer::resetCarousel() {
  _pageIdx = 0;
  _pageSwitchMs = millis();
}

// ---------------------------------------------------------------------------
//  Event overlays
// ---------------------------------------------------------------------------

// Greedy word wrap into `out`, at most `maxLines` lines of `maxW` pixels in
// whatever font is currently selected. Returns how many lines were used.
//
// A word longer than the line is hard-broken rather than dropped: order titles
// are written by a game studio, not by this renderer, and one unbroken
// 40-character string should not blank a screen. The last line is ellipsed if
// there is more text than room, so a truncated briefing looks truncated rather
// than finished.
int8_t HUDRenderer::wrapText(const String &s, int16_t maxW, int8_t maxLines,
                             String *out) {
  int8_t used = 0;
  int idx = 0;
  const int len = s.length();

  while (idx < len && used < maxLines) {
    while (idx < len && s[idx] == ' ') idx++;  // eat run-on spaces
    if (idx >= len) break;

    int fit = idx;      // one past the last character known to fit
    int lastSpace = -1; // last space seen inside that run
    while (fit < len) {
      if (s[fit] == '\n') break;
      const String probe = s.substring(idx, fit + 1);
      if (_tft.textWidth(probe.c_str()) > maxW) break;
      if (s[fit] == ' ') lastSpace = fit;
      fit++;
    }

    int end = fit;
    if (fit < len && s[fit] != '\n' && lastSpace > idx) end = lastSpace;
    if (end <= idx) end = idx + 1;  // hard break: nothing fit, take one char

    out[used] = s.substring(idx, end);
    out[used].trim();
    used++;
    idx = end;
    if (idx < len && s[idx] == '\n') idx++;
  }

  // Anything left over is signalled on the final line rather than silently
  // dropped.
  if (idx < len && used > 0) {
    String &tail = out[used - 1];
    while (tail.length() > 1 &&
           _tft.textWidth((tail + "...").c_str()) > maxW)
      tail.remove(tail.length() - 1);
    tail += "...";
  }
  return used;
}

void HUDRenderer::drawOverlay(const HudModel &m, time_t nowUtc) {
  (void)nowUtc;
  const MajorOrder &o = m.overlaySubject;
  const bool verdict = (m.overlay == kOverlaySuccess || m.overlay == kOverlayFailure);
  const uint16_t accent = m.overlay == kOverlaySuccess  ? theme::green
                          : m.overlay == kOverlayFailure ? theme::red
                                                         : theme::gold;

  _tft.fillScreen(theme::bg);

  // A verdict gets a band of its own colour across the full width; an
  // announcement gets the HUD's ordinary gold frame. That difference is the
  // fastest thing to read from across a room -- the colour says what happened
  // before any of the words have been.
  const int16_t bandY = layout::frameY + 26;
  const int16_t bandH = verdict ? 76 : 54;
  if (verdict) {
    _tft.fillRect(0, bandY, layout::screenW, bandH, accent);
  } else {
    _tft.fillRect(0, bandY, layout::screenW, bandH, theme::panel);
    _tft.drawFastHLine(0, bandY, layout::screenW, theme::goldDim);
    _tft.drawFastHLine(0, bandY + bandH - 1, layout::screenW, theme::goldDim);
  }

  drawFrame();

  // --- the banner word -----------------------------------------------------
  const char *word = m.overlay == kOverlaySuccess    ? "ORDER COMPLETE"
                     : m.overlay == kOverlayFailure  ? "ORDER FAILED"
                                                     : "NEW MAJOR ORDER";
  _tft.setFreeFont(verdict ? FONT_HEADLINE : FONT_HEADLINE_SM);
  _tft.setTextDatum(MC_DATUM);
  // Ink on the band, not a tint of it: a verdict's band is a saturated fill
  // and mid-tone text on it is the one thing that would be unreadable at a
  // glance, which is the entire job of this screen.
  _tft.setTextColor(verdict ? theme::bg : accent, verdict ? accent : theme::panel);
  _tft.drawString(word, layout::screenW / 2, bandY + bandH / 2);

  // --- the text block ------------------------------------------------------
  //
  // Both halves are wrapped before either is drawn, so the whole block can be
  // centred in the space the band and the dismiss line leave between them.
  // Top-aligning it is what the layout did first, and a verdict -- which is
  // only ever two or three short lines -- ended up in the top third of the
  // panel with half a screen of nothing under it.
  const int16_t textW = layout::frameW - 2 * layout::padX;
  const int16_t textX = layout::screenW / 2;
  const int16_t dismissY = layout::screenH - layout::frameY - 22;

  String titleLines[2];
  _tft.setFreeFont(FONT_VALUE);
  const String title = o.title.length() ? o.title : String(F("MAJOR ORDER"));
  const int8_t titleN = wrapText(title, textW, 2, titleLines);

  // An announcement leads with the briefing, because that is the thing being
  // announced. A verdict does not repeat it: the order is over, and what is
  // worth saying is how it ended and what it paid.
  String bodyLines[4];
  int8_t bodyN = 0;
  int8_t goldLine = -1;  // index into bodyLines that is a reward, not prose
  _tft.setFreeFont(FONT_BODY);
  if (!verdict) {
    bodyN = wrapText(o.briefing, textW, 4, bodyLines);
  } else {
    // How far each objective got. On a success this is a formality; on a
    // failure it is the only place a near miss is visible at all, and "3 of 4
    // objectives met" is a materially different evening from "0 of 4".
    if (o.taskCount > 0) {
      int done = 0;
      for (int i = 0; i < o.taskCount; i++)
        if (o.tasks[i].complete) done++;
      char summary[64];
      snprintf(summary, sizeof(summary), "%d of %d objectives met", done, o.taskCount);
      bodyLines[bodyN++] = summary;
    }
    if (m.overlay == kOverlaySuccess && o.rewardAmount > 0) {
      char reward[48];
      snprintf(reward, sizeof(reward), "%d MEDALS AWARDED", (int)o.rewardAmount);
      goldLine = bodyN;
      bodyLines[bodyN++] = reward;
    }
  }

  const int16_t titleLead = 24;
  const int16_t bodyLead = verdict ? 22 : 19;
  const int16_t gap = 8;
  const int16_t blockH = titleN * titleLead + (bodyN ? gap + bodyN * bodyLead : 0);

  const int16_t areaTop = bandY + bandH;
  const int16_t areaBottom = dismissY - 18;  // air above the dismiss line
  int16_t y = areaTop + ((areaBottom - areaTop) - blockH) / 2;
  // A four-line briefing can be taller than the space; let it start just under
  // the band and run long rather than creeping up over it.
  if (y < areaTop + 14) y = areaTop + 14;

  _tft.setFreeFont(FONT_VALUE);
  _tft.setTextColor(theme::text, theme::bg);
  for (int8_t i = 0; i < titleN; i++) {
    _tft.drawString(titleLines[i], textX, y + titleLead / 2);
    y += titleLead;
  }
  if (bodyN) y += gap;

  _tft.setFreeFont(FONT_BODY);
  for (int8_t i = 0; i < bodyN; i++) {
    _tft.setTextColor(i == goldLine ? theme::gold : theme::grey, theme::bg);
    _tft.drawString(bodyLines[i], textX, y + bodyLead / 2);
    y += bodyLead;
  }

  // --- the way out ---------------------------------------------------------
  //
  // Named explicitly because this screen has taken over the panel and there is
  // no other affordance on it. The wording covers the fallback too: the timer
  // exists so a dead panel cannot strand the HUD here, and someone reading
  // this should not be left wondering whether anything will ever move again.
  _tft.setFreeFont(FONT_LABEL);
  _tft.setTextColor(theme::goldMute, theme::bg);
  _tft.drawString(F("TOUCH TO DISMISS"), layout::screenW / 2, dismissY);
  _tft.setTextDatum(TL_DATUM);
}

void HUDRenderer::update(const HudModel &m, time_t nowUtc) {
  // An overlay owns the panel outright: no chrome, no carousel, no clocks.
  // Repainted only when the announcement itself changes, so the screen is
  // static while it waits to be acknowledged.
  if (m.overlay != kOverlayNone) {
    const String sig = String((int)m.overlay) + "|" + String((int)m.overlaySubject.id);
    if (sig != _overlaySig) {
      _overlaySig = sig;
      drawOverlay(m, nowUtc);
    }
    return;
  }
  // Leaving an overlay means everything underneath it has been painted over.
  if (_overlaySig.length()) {
    _overlaySig = "";
    invalidate();
  }

  if (!_chromeDrawn) {
    _tft.fillScreen(theme::bg);
    drawFrame();
    // The rest is left to drawBody(), which is about to run: the cleared
    // _contentSig guarantees it.
    _chromeDrawn = true;
    _contentSig = "";
    _targetSig = "";
    _campaignSig = "";
    _wifiSig = -1;
  }

  updateCarousel(m);

  // A page-type crossing (MO card <-> campaign card) needs the full drawBody()
  // repaint even when contentSignature(m) itself didn't change -- the two card
  // types use different header/footer geometry, and nothing else here notices
  // "only which page we're looking at changed."
  const bool cardModeNow = pageIsCard(m, _pageIdx);
  const bool boundaryCrossed = cardModeNow != _lastCardMode;

  const String sig = contentSignature(m);
  if (sig != _contentSig || boundaryCrossed) {
    _contentSig = sig;
    drawBody(m, nowUtc);
  } else if (_cardMode && targetSignature(m, _pageIdx) != _targetSig) {
    // The carousel moved within the MO's own targets, or this target's data did.
    drawCard(m);
  } else if (!_cardMode && pageCount(m) > 0) {
    // As in drawBody(): campaign pages only exist with no order active, so
    // the page index is the campaign index.
    const uint8_t ci = _pageIdx;
    const String csig = campaignPageSignature(m, ci);
    if (csig != _campaignSig) {
      _campaignSig = csig;
      drawCampaignBody(m, m.campaigns[ci], m.campaignHistory[ci]);
    }
  }

  _lastCardMode = cardModeNow;

  // After the branch above, not before: a drawBody() repaint clears the row
  // this paints into. Its own signature makes the second call a no-op on the
  // frames where drawBody() already ran, and on a carousel step -- where none
  // of the branches above touch the header -- it is the only thing that moves
  // the pips.
  drawHeader(m);
  if (_cardMode) drawCardClocks(m, nowUtc);
  drawFooter(m, nowUtc);
  drawWifi(m.wifiUp);
}

void HUDRenderer::showBoot(const char *status) {
  invalidate();
  _cardMode = false;
  _tft.fillScreen(theme::bg);
  drawFrame();
  drawStatusHeader();
  // The Helldivers II title mark, boot screen only -- the idle screen keeps
  // the SEAF emblem as its own centrepiece. Cut at the full 440px content
  // width so it carries the screen; only scaled and recoloured, never redrawn.
  _tft.drawBitmap(padX, 48, icons::hd2LogoBoot, icons::hd2LogoBootW,
                  icons::hd2LogoBootH, theme::gold);
  textBox(padX, 232, contentW, 22, theme::bg, FONT_VALUE, theme::text, MC_DATUM,
          F("MAJOR ORDER MONITOR"));
  textBox(padX, 264, contentW, 20, theme::bg, FONT_BODY, theme::grey, MC_DATUM,
          String(status));
  // Next update() must repaint from scratch.
  _chromeDrawn = false;
}

void HUDRenderer::showPortal(const char *ssid, const char *pass) {
  invalidate();
  _cardMode = false;
  _tft.fillScreen(theme::bg);
  drawFrame();
  drawStatusHeader();
  textBox(padX, 60, contentW, 30, theme::bg, FONT_DISPLAY, theme::gold, MC_DATUM,
          F("WIFI SETUP"));
  textBox(padX, 104, contentW, 20, theme::bg, FONT_BODY, theme::text, MC_DATUM,
          F("Join this network from a phone or laptop,"));
  textBox(padX, 124, contentW, 20, theme::bg, FONT_BODY, theme::text, MC_DATUM,
          F("then set WiFi and UTC offset in the page that opens."));

  drawStatBox(padX, statY, kStatW, statH, F("NETWORK"), String(ssid), theme::gold);
  drawStatBox(padX + kStatW + statGap, statY, kStatW, statH, F("PASSWORD"),
              String(pass), theme::gold);

  textBox(padX, 224, contentW, 20, theme::bg, FONT_BODY, theme::grey, MC_DATUM,
          F("If no page opens, browse to 192.168.4.1"));
  _chromeDrawn = false;
}

// ---------------------------------------------------------------------------
//  First-boot touch calibration prompt
//
//  The reference art is a photograph of a ship's bridge with a warning card
//  over it. What is reproduced here is the card: the bands and their
//  proportions, the badge, the reticle, the hazard bar. The photograph and the
//  game's wordmark are not, deliberately -- see the note over the cal*
//  constants in config.h.
//
//  Drawn from primitives rather than added to hud_icons.h. A 76px reticle as a
//  1-bit bitmap is 722 bytes of an image already sitting at 96% of its flash
//  slot, for a shape that is two circles and eight straight runs; the hazard
//  bar could not be a bitmap at all without storing it at full width.
// ---------------------------------------------------------------------------

// A reticle with a hand tapping its centre, in an `s`-square box at (x,y).
// Ring, four crosshair ticks through it, a small target at the middle, and a
// bracket at each corner of the box -- the reference's own construction. The
// hand comes in from the lower right at 45 degrees with the fingertip on the
// centre dot, which is what makes it read as "put a finger here" rather than
// as a target to be shot at; a hand standing upright in the middle of the ring
// reads as a raised finger and nothing else.
//
// Sized in fractions of `s` only where the fraction is the point. The rest is
// in pixels: this is one icon at one size, and naming a constant for the
// fingertip's offset would suggest it means something elsewhere.
void HUDRenderer::drawCalReticle(int16_t x, int16_t y, int16_t s) {
  const int16_t cx = x + s / 2, cy = y + s / 2;
  const int16_t r = s * 13 / 40;  // 29 at s=92, leaving the ticks room outside

  // Three concentric circles: a 1px ring at this diameter is a dotted line by
  // the time the panel's own subpixel structure has had it, and the reference's
  // ring is heavy enough to carry the icon on its own.
  for (int16_t i = 0; i < 3; i++) _tft.drawCircle(cx, cy, r - i, theme::gold);

  // Crosshair ticks, crossing the ring rather than stopping outside it.
  const int16_t t0 = r - 6, t1 = r + 9, tw = t1 - t0;
  _tft.fillRect(cx - 1, cy - t1, 3, tw, theme::gold);
  _tft.fillRect(cx - 1, cy + t0, 3, tw, theme::gold);
  _tft.fillRect(cx - t1, cy - 1, tw, 3, theme::gold);
  _tft.fillRect(cx + t0, cy - 1, tw, 3, theme::gold);

  // The target at the middle, which is what the finger is pointing at.
  _tft.drawCircle(cx, cy, 10, theme::gold);
  _tft.drawCircle(cx, cy, 9, theme::gold);
  _tft.fillCircle(cx, cy, 3, theme::gold);

  // Corner brackets, 2px thick, drawn as pairs of runs -- there is no
  // drawLine() here and none is needed for right angles.
  //
  // Three of them, not four: the hand comes in over the bottom-right corner
  // and covers it, exactly as it does in the reference. Drawing one there and
  // letting the hand's halo bite a piece out of it looks like damage.
  const int16_t b = 15, x1 = x + s - 1, y1 = y + s - 1;
  for (int16_t i = 0; i < 2; i++) {
    _tft.drawFastHLine(x, y + i, b, theme::gold);
    _tft.drawFastVLine(x + i, y, b, theme::gold);
    _tft.drawFastHLine(x1 - b + 1, y + i, b, theme::gold);
    _tft.drawFastVLine(x1 - i, y, b, theme::gold);
    _tft.drawFastHLine(x, y1 - i, b, theme::gold);
    _tft.drawFastVLine(x + i, y1 - b + 1, b, theme::gold);
  }

  // The hand, drawn twice: once in the card's own fill, three pixels proud all
  // round, then in gold on top of that. The halo is not decoration -- the hand
  // crosses the ring and the bottom-right bracket, and without a gap the three
  // gold shapes merge into one blob. The reference solves the same problem by
  // outlining the hand in black.
  for (int8_t pass = 0; pass < 2; pass++) {
    const uint16_t c = pass ? theme::gold : theme::panel;
    const int16_t g = pass ? 0 : 2;

    // Index finger: a bar at 45 degrees, from the centre dot down to the
    // knuckles. Two triangles, because a quad is what four points make and
    // there is no primitive for one.
    const int16_t ax = cx - g, ay = cy + 4;
    const int16_t bx = cx + 4, by = cy - g;
    const int16_t px = cx + 22 + g, py = cy + 16;
    const int16_t qx = cx + 16, qy = cy + 22 + g;
    _tft.fillTriangle(ax, ay, bx, by, px, py, c);
    _tft.fillTriangle(ax, ay, px, py, qx, qy, c);
    _tft.fillCircle(cx + 2, cy + 2, 2 + g, c);  // rounded fingertip

    // Folded fingers and palm: a rounded block below and right of that, and a
    // thumb bump on the near side.
    const int16_t hx = cx + 12 - g, hy = cy + 13 - g;
    const int16_t hw = 25 + 2 * g, hh = 23 + 2 * g, hr = 6 + g;
    _tft.fillRect(hx + hr, hy, hw - 2 * hr, hh, c);
    _tft.fillRect(hx, hy + hr, hw, hh - 2 * hr, c);
    _tft.fillCircle(hx + hr, hy + hr, hr, c);
    _tft.fillCircle(hx + hw - hr - 1, hy + hr, hr, c);
    _tft.fillCircle(hx + hr, hy + hh - hr - 1, hr, c);
    _tft.fillCircle(hx + hw - hr - 1, hy + hh - hr - 1, hr, c);
    _tft.fillCircle(cx + 10, cy + 31, 6 + g, c);
  }
}

// The diagonal hazard bar along the card's bottom edge.
//
// Built as one horizontal run per row rather than as diagonal lines: at 45
// degrees a stripe's start moves exactly one pixel per row, so the whole band
// is a stack of offset runs -- which is both what the available primitives can
// draw and faster than the general case would be.
void HUDRenderer::drawHazardBar(int16_t x, int16_t y, int16_t w, int16_t h) {
  _tft.fillRect(x, y, w, h, theme::bg);
  for (int16_t row = 0; row < h; row++) {
    // Stripes lean up-and-to-the-right, so their start walks left as the row
    // walks down. The modulo keeps the first one on screen for wide bars.
    for (int16_t sx = -(row % calStripePitch) - calStripePitch; sx < w;
         sx += calStripePitch) {
      int16_t a = sx, b = sx + calStripeInk;
      if (b <= 0 || a >= w) continue;
      if (a < 0) a = 0;
      if (b > w) b = w;
      _tft.drawFastHLine(x + a, y + row, b - a, theme::gold);
    }
  }
}

void HUDRenderer::showTouchPrompt() {
  invalidate();
  _cardMode = false;
  _tft.fillScreen(theme::bg);
  drawFrame();
  drawStatusHeader();

  // --- the card ------------------------------------------------------------
  _tft.fillRect(calCardX, calCardY, calCardW, calCardH, theme::panel);
  _tft.drawRect(calCardX, calCardY, calCardW, calCardH, theme::gold);
  const int16_t inX = calCardX + 1, inW = calCardW - 2;
  const int16_t headRuleY = calCardY + calHeadH;
  const int16_t bodyY = headRuleY + 1;
  const int16_t stripeY = calCardY + calCardH - calStripeH;

  // --- header: badge, title, rule ------------------------------------------
  const int16_t badgeX = calCardX + calBadgeInset;
  const int16_t badgeY = calCardY + 1 + (calHeadH - 1 - calBadgeH) / 2;
  // A gold tab whose trailing edge leans outward on the way down, so the tab is
  // wider at its foot than at its head. The slant is what stops it reading as a
  // plain rectangle at 40px, and its direction is the reference's.
  _tft.fillRect(badgeX, badgeY, calBadgeW - calBadgeSlant, calBadgeH, theme::gold);
  _tft.fillTriangle(badgeX + calBadgeW - calBadgeSlant, badgeY,
                    badgeX + calBadgeW - calBadgeSlant, badgeY + calBadgeH - 1,
                    badgeX + calBadgeW, badgeY + calBadgeH - 1, theme::gold);
  // The warning triangle is knocked out of the tab in the card's own fill
  // colour, with a gold exclamation inside it -- gold-on-dark-on-gold, exactly
  // as in the reference. (The task file's parenthetical suggested theme::red
  // here; the reference supersedes it. One constant if that is wrong.)
  const int16_t tcx = badgeX + (calBadgeW - calBadgeSlant) / 2;
  const int16_t tTop = badgeY + 5, tBot = badgeY + calBadgeH - 5;
  _tft.fillTriangle(tcx, tTop, tcx - 11, tBot, tcx + 11, tBot, theme::panel);
  _tft.fillRect(tcx - 1, tTop + 8, 3, 7, theme::gold);
  _tft.fillRect(tcx - 1, tBot - 4, 3, 3, theme::gold);

  // Label weight, not value weight: "TOUCH CALIBRATION REQUIRED" is 394px at
  // FONT_VALUE and there are 364 to put it in -- and label weight is also the
  // proportionally right answer, the reference's header caps being about 7.5%
  // of the card's height, which on 204px is the ~13px FreeSansBold9pt gives.
  const int16_t titleX = badgeX + calBadgeW + calTitleGap;
  textBox(titleX, badgeY, calCardX + calCardW - calTextPadR - titleX, calBadgeH,
          theme::panel, FONT_LABEL, theme::gold, ML_DATUM,
          F("TOUCH CALIBRATION REQUIRED"));
  _tft.drawFastHLine(inX, headRuleY, inW, theme::gold);

  // --- body: reticle, then the copy beside it ------------------------------
  const int16_t bodyH = stripeY - 1 - bodyY;
  drawCalReticle(calCardX + calIconInset, bodyY + (bodyH - calIconS) / 2, calIconS);

  // TL_DATUM, unlike everything else on the panel -- see the note over the
  // calAddrDy/calLineH constants. These are the HUD's only mixed-case rows and
  // the middle datum's ascent-only centring drops their descenders out of the
  // sprite unless the rows are made a third taller than the type needs.
  const int16_t textX = calCardX + calIconInset + calIconS + calTextGap;
  const int16_t textW = calCardX + calCardW - calTextPadR - textX;
  textBox(textX, bodyY + calAddrDy, textW, calAddrH, theme::panel, FONT_LABEL,
          theme::text, TL_DATUM, F("Helldiver,"));

  // Written for this panel rather than lifted from the reference: the wording
  // there is the game's, and this one has to say what this device actually
  // wants, which is a calibration and not a mission.
  int16_t ly = bodyY + calCopyDy;
  textBox(textX, ly, textW, calLineH, theme::panel, FONT_BODY, theme::text,
          TL_DATUM, F("This terminal's touch interface is"));
  ly += calLineH;
  textBox(textX, ly, textW, calLineH, theme::panel, FONT_BODY, theme::text,
          TL_DATUM, F("not yet calibrated."));
  ly += calLineH + calParaGap;
  textBox(textX, ly, textW, calLineH, theme::panel, FONT_BODY, theme::grey,
          TL_DATUM, F("Run a calibration to ensure accurate"));
  ly += calLineH;
  textBox(textX, ly, textW, calLineH, theme::panel, FONT_BODY, theme::grey,
          TL_DATUM, F("targeting and stratagem deployment."));

  // --- hazard bar ----------------------------------------------------------
  // stripeY-1 is the rule; the stripes run from stripeY down to the row above
  // the card's bottom border, which is calStripeH-1 rows in all.
  _tft.drawFastHLine(inX, stripeY - 1, inW, theme::gold);
  drawHazardBar(inX, stripeY, inW, calStripeH - 1);

  // --- the way out ---------------------------------------------------------
  // The only affordance on the screen, so it is named outright. It does not
  // promise the wait is unlimited, because it is not: main.cpp gives this a
  // bounded wait and boots on regardless, and a unit nobody was standing in
  // front of ends up on the HUD with the footer hint carrying the offer.
  textBox(padX, calCtaY - calCtaH / 2, contentW, calCtaH, theme::bg, FONT_LABEL,
          theme::gold, MC_DATUM, F("TOUCH ANYWHERE TO BEGIN"));

  _chromeDrawn = false;
}
